import { unstable_noStore as noStore } from 'next/cache';

export default function Home() {
  // Log page view without blocking the response
  noStore();

  // Schedule analytics logging after response is sent
  if (typeof window === 'undefined') {
    // This runs on the server
    const logAnalytics = async () => {
      try {
        // Simulate analytics service call
        await fetch('https://analytics.example.com/log', {
          method: 'POST',
          body: JSON.stringify({
            page: 'home',
            timestamp: new Date().toISOString()
          }),
          headers: {
            'Content-Type': 'application/json'
          }
        });
      } catch (error) {
        console.error('Analytics logging failed:', error);
      }
    };

    // Schedule the work to run after the response is sent
    logAnalytics().catch(console.error);
  }

  return (
    <main>
      <h1>Welcome to our website!</h1>
      <p>Your visit has been logged for analytics purposes.</p>
    </main>
  );
}

